-- テーブル削除
DROP TABLE IF EXISTS mst_treatment_status_disp_item;
-- テーブル作成
CREATE TABLE mst_treatment_status_disp_item
(
    item_cd integer NOT NULL,  --レイアウト表示項目番号
    data_class character varying(1) NOT NULL DEFAULT '0',  --データ取得種別
    machine_class character varying(1) NOT NULL DEFAULT '0',  --装置種別
    item_name character varying NOT NULL,  --項目名
    table_name character varying,  --参照先テーブル名
    field_name character varying,  --参照先フィールド名
    json_key_name character varying,  --参照先JSONキー名
    disp_order integer DEFAULT 0,  --表示順
    is_disp character varying(1) DEFAULT '1',  --表示フラグ
    is_del character varying(1) DEFAULT '0',  --削除フラグ
    reg_date timestamp(3),  --登録日時
    up_date timestamp(3),  --更新日時

    CONSTRAINT unq_mst_treatment_status_disp_item_01 PRIMARY KEY (item_cd)
)
WITH (
    OIDS=FALSE
);
-- コメント追加
COMMENT ON TABLE "mst_treatment_status_disp_item" IS E'治療状況レイアウト表示項目マスタ';
COMMENT ON COLUMN "mst_treatment_status_disp_item"."item_cd" IS E'レイアウト表示項目番号';
COMMENT ON COLUMN "mst_treatment_status_disp_item"."data_class" IS E'データ取得種別';
COMMENT ON COLUMN "mst_treatment_status_disp_item"."machine_class" IS E'装置種別';
COMMENT ON COLUMN "mst_treatment_status_disp_item"."item_name" IS E'項目名';
COMMENT ON COLUMN "mst_treatment_status_disp_item"."table_name" IS E'参照先テーブル名';
COMMENT ON COLUMN "mst_treatment_status_disp_item"."field_name" IS E'参照先フィールド名';
COMMENT ON COLUMN "mst_treatment_status_disp_item"."json_key_name" IS E'参照先JSONキー名';
COMMENT ON COLUMN "mst_treatment_status_disp_item"."disp_order" IS E'表示順';
COMMENT ON COLUMN "mst_treatment_status_disp_item"."is_disp" IS E'表示フラグ';
COMMENT ON COLUMN "mst_treatment_status_disp_item"."is_del" IS E'削除フラグ';
COMMENT ON COLUMN "mst_treatment_status_disp_item"."reg_date" IS E'登録日時';
COMMENT ON COLUMN "mst_treatment_status_disp_item"."up_date" IS E'更新日時';

